choose.when:
AND EXISTS (
    SELECT 1 FROM im_task_participant p
    WHERE p.company_id = d.company_id AND p.task_id = d.task_id AND p.user_id = #{userId}
)

choose.otherwise:
AND (
    d.creator_id = #{userId}
    OR d.reviewer_id = #{userId}
    OR EXISTS (
        SELECT 1 FROM im_task_participant p
        WHERE p.company_id = d.company_id AND p.task_id = d.task_id AND p.user_id = #{userId}
    )
)

mapper.select:
SELECT 

WHERE d.task_id = #{taskId} AND d.tenant_id = #{tenantId} AND d.company_id = #{tenantId}
LIMIT 1

SELECT 

WHERE d.tenant_id = #{tenantId} AND d.company_id = #{tenantId}
  AND d.task_id IN
  #{taskId}

SELECT 

WHERE d.tenant_id = #{tenantId} AND d.company_id = #{tenantId}




            AND d.overdue_at IS NOT NULL AND d.workflow_state NOT IN ('completed', 'cancelled')


            AND d.workflow_state = #{state}




    AND (d.updated_at < #{cursorTime} OR (d.updated_at = #{cursorTime} AND d.task_id < #{cursorTaskId}))

ORDER BY d.updated_at DESC, d.task_id DESC
LIMIT #{limit}
